var _0004_ap_preseason_default = "-- 2026 preseason AP Top 25 (released Aug 17, 2026). BYU/USC tied at 14.\nupdate rankings set ap_rank = null where season = 2026 and week = 0;\n\nupdate rankings r\nset ap_rank = v.rk\nfrom teams t\njoin (values\n  ('ohio-state', 1),\n  ('oregon', 2),\n  ('georgia', 3),\n  ('notre-dame', 4),\n  ('texas', 5),\n  ('indiana', 6),\n  ('miami', 7),\n  ('texas-am', 8),\n  ('ole-miss', 9),\n  ('oklahoma', 10),\n  ('lsu', 11),\n  ('texas-tech', 12),\n  ('alabama', 13),\n  ('byu', 14),\n  ('usc', 14),\n  ('michigan', 16),\n  ('washington', 17),\n  ('penn-state', 18),\n  ('smu', 19),\n  ('tennessee', 20),\n  ('utah', 21),\n  ('iowa', 22),\n  ('houston', 23),\n  ('louisville', 24),\n  ('missouri', 25)\n) as v(slug, rk) on v.slug = t.slug\nwhere r.team_id = t.id and r.season = 2026 and r.week = 0;\n";
var _0005_c20_coach_change_default = "-- C20 coach-change HX moves (2026 week 0 rankings only).\n-- Ten Connelly-residual adjustments. Re-rank all 136.\n-- Week 0 scheduled matchup HX is frozen so win% / SU picks do not move\n-- (Hawaiʻi at Stanford stays Hawaiʻi 53.8% / HAW −1.4).\n\nalter table games add column if not exists lock_home_hx double precision;\nalter table games add column if not exists lock_away_hx double precision;\n\n-- Snapshot current ratings onto Week 0 games BEFORE the HX updates.\nupdate games g\nset lock_home_hx = hr.hx_rating,\n    lock_away_hx = ar.hx_rating\nfrom rankings hr, rankings ar\nwhere hr.team_id = g.home_team_id and hr.season = 2026 and hr.week = 0\n  and ar.team_id = g.away_team_id and ar.season = 2026 and ar.week = 0\n  and g.kickoff_date <= date '2026-08-30';\n\n-- Apply the ten HX moves.\n-- Ole Miss: Lane Kiffin → Pete Golding\nupdate rankings set hx_rating = 5.492 where team_id = 5 and season = 2026 and week = 0;\n\n-- Florida: Billy Napier → Jon Sumrall\nupdate rankings set hx_rating = 3.506 where team_id = 33 and season = 2026 and week = 0;\n\n-- South Florida: Alex Golesh → Brian Hartline\nupdate rankings set hx_rating = 0.187 where team_id = 46 and season = 2026 and week = 0;\n\n-- Tulane: Jon Sumrall → Will Hall\nupdate rankings set hx_rating = -1.144 where team_id = 61 and season = 2026 and week = 0;\n\n-- North Texas: Eric Morris → Neal Brown\nupdate rankings set hx_rating = -2.224 where team_id = 62 and season = 2026 and week = 0;\n\n-- UConn: Jim Mora → Jason Candle\nupdate rankings set hx_rating = -1.867 where team_id = 74 and season = 2026 and week = 0;\n\n-- Virginia Tech: Brent Pry → James Franklin\nupdate rankings set hx_rating = 1.156 where team_id = 80 and season = 2026 and week = 0;\n\n-- Stanford: Troy Taylor / Frank Reich (i) → Tavita Pritchard\nupdate rankings set hx_rating = -0.759 where team_id = 102 and season = 2026 and week = 0;\n\n-- Oregon State: Trent Bray → JaMarcus Shephard\nupdate rankings set hx_rating = -1.148 where team_id = 106 and season = 2026 and week = 0;\n\n-- Oklahoma State: Mike Gundy → Eric Morris\nupdate rankings set hx_rating = -1.255 where team_id = 119 and season = 2026 and week = 0;\n\n-- Re-rank all 136 by HX (ties broken by team_id).\nwith ordered as (\n  select team_id,\n         row_number() over (order by hx_rating desc, team_id) as rk\n  from rankings\n  where season = 2026 and week = 0\n)\nupdate rankings r\nset hx_rank = o.rk\nfrom ordered o\nwhere r.team_id = o.team_id and r.season = 2026 and r.week = 0;\n\n-- Playoff odds are a function of rank. Remap the existing curve onto the new order.\nwith odds as (\n  select * from (values\n    (1, 98.4),\n    (2, 97.7),\n    (3, 96.7),\n    (4, 95.4),\n    (5, 93.6),\n    (6, 91.1),\n    (7, 87.7),\n    (8, 83.3),\n    (9, 77.7),\n    (10, 70.9),\n    (11, 63.1),\n    (12, 54.5),\n    (13, 45.5),\n    (14, 36.9),\n    (15, 29.1),\n    (16, 22.3),\n    (17, 16.7),\n    (18, 12.3),\n    (19, 8.9),\n    (20, 6.4),\n    (21, 4.6),\n    (22, 3.3),\n    (23, 2.3),\n    (24, 1.6),\n    (25, 1.1),\n    (26, 0.8),\n    (27, 0.6),\n    (28, 0.4),\n    (29, 0.3),\n    (30, 0.2),\n    (31, 0.1),\n    (32, 0.1),\n    (33, 0.1),\n    (34, 0.0),\n    (35, 0.0),\n    (36, 0.0),\n    (37, 0.0),\n    (38, 0.0),\n    (39, 0.0),\n    (40, 0.0),\n    (41, 0.0),\n    (42, 0.0),\n    (43, 0.0),\n    (44, 0.0),\n    (45, 0.0),\n    (46, 0.0),\n    (47, 0.0),\n    (48, 0.0),\n    (49, 0.0),\n    (50, 0.0),\n    (51, 0.0),\n    (52, 0.0),\n    (53, 0.0),\n    (54, 0.0),\n    (55, 0.0),\n    (56, 0.0),\n    (57, 0.0),\n    (58, 0.0),\n    (59, 0.0),\n    (60, 0.0),\n    (61, 0.0),\n    (62, 0.0),\n    (63, 0.0),\n    (64, 0.0),\n    (65, 0.0),\n    (66, 0.0),\n    (67, 0.0),\n    (68, 0.0),\n    (69, 0.0),\n    (70, 0.0),\n    (71, 0.0),\n    (72, 0.0),\n    (73, 0.0),\n    (74, 0.0),\n    (75, 0.0),\n    (76, 0.0),\n    (77, 0.0),\n    (78, 0.0),\n    (79, 0.0),\n    (80, 0.0),\n    (81, 0.0),\n    (82, 0.0),\n    (83, 0.0),\n    (84, 0.0),\n    (85, 0.0),\n    (86, 0.0),\n    (87, 0.0),\n    (88, 0.0),\n    (89, 0.0),\n    (90, 0.0),\n    (91, 0.0),\n    (92, 0.0),\n    (93, 0.0),\n    (94, 0.0),\n    (95, 0.0),\n    (96, 0.0),\n    (97, 0.0),\n    (98, 0.0),\n    (99, 0.0),\n    (100, 0.0),\n    (101, 0.0),\n    (102, 0.0),\n    (103, 0.0),\n    (104, 0.0),\n    (105, 0.0),\n    (106, 0.0),\n    (107, 0.0),\n    (108, 0.0),\n    (109, 0.0),\n    (110, 0.0),\n    (111, 0.0),\n    (112, 0.0),\n    (113, 0.0),\n    (114, 0.0),\n    (115, 0.0),\n    (116, 0.0),\n    (117, 0.0),\n    (118, 0.0),\n    (119, 0.0),\n    (120, 0.0),\n    (121, 0.0),\n    (122, 0.0),\n    (123, 0.0),\n    (124, 0.0),\n    (125, 0.0),\n    (126, 0.0),\n    (127, 0.0),\n    (128, 0.0),\n    (129, 0.0),\n    (130, 0.0),\n    (131, 0.0),\n    (132, 0.0),\n    (133, 0.0),\n    (134, 0.0),\n    (135, 0.0),\n    (136, 0.0)\n  ) as v(rk, odds)\n)\nupdate rankings r\nset playoff_odds = odds.odds\nfrom odds\nwhere r.hx_rank = odds.rk and r.season = 2026 and r.week = 0;\n\n";
var _0006_schedule_default = "-- Schedule hub: kick times, Vegas (home-perspective + total), and final scores.\n-- HASHMARK spreads stay computed from lock/current HX — never stored here.\n-- Research CFB locked the Week 0 consensus. NDSU / Sac State / EMU stay off the 136.\n\nalter table games add column if not exists kickoff_at timestamptz;\nalter table games add column if not exists vegas_spread double precision;\nalter table games add column if not exists vegas_total double precision;\nalter table games add column if not exists home_score int;\nalter table games add column if not exists away_score int;\nalter table games add column if not exists status text not null default 'scheduled';\n\n-- Dublin: TCU listed home, Neutral. Opened −6.5; consensus TCU −8.5 / 46.5.\nupdate games g\nset kickoff_at = timestamptz '2026-08-29 16:00:00+00',\n    vegas_spread = 8.5,\n    vegas_total = 46.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'tcu' and a.slug = 'north-carolina';\n\nupdate games g\nset kickoff_at = timestamptz '2026-08-29 19:00:00+00',\n    vegas_spread = 38.5,\n    vegas_total = 61.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'usc' and a.slug = 'san-jose-state'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset kickoff_at = timestamptz '2026-08-29 19:30:00+00',\n    vegas_spread = 4,\n    vegas_total = 51.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'virginia' and a.slug = 'nc-state'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset kickoff_at = timestamptz '2026-08-29 23:00:00+00',\n    vegas_spread = 4,\n    vegas_total = 48.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'stanford' and a.slug = 'hawaii'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset kickoff_at = timestamptz '2026-08-29 23:00:00+00',\n    vegas_spread = 31.5,\n    vegas_total = 53.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'florida-state' and a.slug = 'new-mexico-state'\n  and g.kickoff_date = date '2026-08-29';\n\n-- 10:00 ET Saturday = 9:00 CT Saturday, still 8/29 in Chicago (seed date is 8/30).\n-- Consensus UNLV −4 / 56.5; Research will refresh if it settles before 9 CT.\nupdate games g\nset kickoff_at = timestamptz '2026-08-30 02:00:00+00',\n    vegas_spread = 4,\n    vegas_total = 56.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'unlv' and a.slug = 'memphis';\n";
var _0007_vegas_lock_default = "-- Research CFB locked Week 0 consensus (spread / total). Idempotent if 0006\n-- already ran with morning placeholders. NDSU / Sac State / EMU stay off the 136.\n\nalter table games add column if not exists vegas_total double precision;\n\nupdate games g\nset vegas_spread = 8.5, vegas_total = 46.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'tcu' and a.slug = 'north-carolina';\n\nupdate games g\nset vegas_spread = 38.5, vegas_total = 61.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'usc' and a.slug = 'san-jose-state'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset vegas_spread = 4, vegas_total = 51.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'virginia' and a.slug = 'nc-state'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset vegas_spread = 4, vegas_total = 48.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'stanford' and a.slug = 'hawaii'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset vegas_spread = 31.5, vegas_total = 53.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'florida-state' and a.slug = 'new-mexico-state'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset vegas_spread = 4, vegas_total = 56.5\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'unlv' and a.slug = 'memphis';\n";
var _0008_week0_finals_default = "-- Week 0 FINALs. Same six as the Sunday tape. NDSU / Sac State stay off the 136.\n-- Scores: away listed first in copy; columns are home_score / away_score.\n\nupdate games g\nset status = 'final', home_score = 10, away_score = 15\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'tcu' and a.slug = 'north-carolina';\n\nupdate games g\nset status = 'final', home_score = 42, away_score = 26\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'usc' and a.slug = 'san-jose-state'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset status = 'final', home_score = 34, away_score = 8\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'virginia' and a.slug = 'nc-state'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset status = 'final', home_score = 37, away_score = 27\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'stanford' and a.slug = 'hawaii'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset status = 'final', home_score = 34, away_score = 17\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'florida-state' and a.slug = 'new-mexico-state'\n  and g.kickoff_date = date '2026-08-29';\n\nupdate games g\nset status = 'final', home_score = 21, away_score = 27\nfrom teams h, teams a\nwhere g.home_team_id = h.id and g.away_team_id = a.id\n  and h.slug = 'unlv' and a.slug = 'memphis';\n";
var _0009_chrome_pass_default = "-- Display name uses the okina. Slug stays hawaii. No HX change.\nupdate teams\nset name = 'Hawaiʻi', short_name = 'Hawaiʻi'\nwhere slug = 'hawaii';\n\n-- Georgia 2026 class avg was mixed 0–1 / 0–100. 247 Composite points ~292 are fine.\n-- Class avg = mean of 247 Composite decimals × 100 (CFBTrack 0.921). Rankings stay frozen.\nupdate recruiting\nset avg_rating = 92.1\nwhere team_id = 1 and class_year = 2026;\n";
